import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

record Item(String name, int count, int price) {
    int subtotal() {
        return count * price;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<Item> items = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            String name = sc.next();
            int count = sc.nextInt();
            int price = sc.nextInt();
            items.add(new Item(name, count, price));
        }

        items.sort(Comparator.comparingInt(Item::subtotal).reversed()
                .thenComparing(Item::name));

        int total = 0;
        for (Item item : items) {
            System.out.println(item.name() + " " + item.subtotal());
            total += item.subtotal();
        }
        System.out.println("合計 " + total);
    }
}

