import java.util.Scanner;

class InvalidScoreException extends Exception {
    InvalidScoreException(String message) {
        super(message);
    }
}

public class Main {

    static int check(int score) throws InvalidScoreException {
        if (score < 0 || score > 100) {
            throw new InvalidScoreException("範囲外: " + score);
        }
        return score;
    }

    static String grade(int score) {
        return switch (score / 10) {
            case 10, 9 -> "A";
            case 8, 7 -> "B";
            case 6 -> "C";
            default -> "D";
        };
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        int sum = 0;
        int validCount = 0;
        int passCount = 0;

        for (int i = 0; i < k; i++) {
            String name = sc.next();
            int score = sc.nextInt();

            try {
                int valid = check(score);
                System.out.println(name + " " + valid + " " + grade(valid));
                sum += valid;
                validCount++;
                if (valid >= 60) {
                    passCount++;
                }
            } catch (InvalidScoreException e) {
                System.out.println(name + " 範囲外");
            }
        }

        System.out.println("平均 " + (validCount == 0 ? 0 : sum / validCount));
        System.out.println("合格 " + passCount);
    }
}
